//! quadratic curves became cubic Béziers, and the three filled shapes were pre-triangulated.
//! Generated by `tools/tabler_rs.py` from `tools/tabler-map.tsv`: regenerate rather than edit by hand.

use egui::{Color32, Painter, Pos2, Rect, Shape, Stroke, pos2, vec2};

/// One drawing step on Tabler's 24-unit grid.
#[derive(Clone, Copy)]
enum Seg {
    /// Start a new outline.
    M(f32, f32),
    /// A whole circle: centre and radius.
    O(f32, f32, f32),
    /// Straight line.
    L(f32, f32),
    /// Cubic curve: two control points, then the end point.
    C(f32, f32, f32, f32, f32, f32),
}

use Seg::{C, L, M, O};

struct Glyph {
    strokes: &'static [Seg],
    fills: &'static [[f32; 6]],
}

